sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float2 center;

half4 main(float2 coord) {
    float2 c = center * size;
    float2 d = coord - c;
    float s = clamp(amount, 0.0, 1.9);
    float4 sum = float4(0);
    float4 weight = float4(0);
    for (int i = 0; i < 48; ++i) {
        float t = float(i) / 47.0;
        float4 w = float4(1.0 - t, 1.0 - abs(2.0 * t - 1.0), t, 1.0);
        sum += float4(image.eval(c + d * (1.0 + s * (t - 0.5)))) * w;
        weight += w;
    }
    float4 result = sum / weight;
    return half4(half3(min(result.rgb, float3(result.a))), half(result.a));
}
